// Updating the DOM by hand
const counter = document.getElementById("counter");
let count = 0;

document.getElementById("increment").addEventListener("click", () => {
  count = count + 1;
  counter.textContent = count;
  if (count > 9) {
    counter.classList.add("warning");
  }
});

